229	\section{Group schemes are separated}
230	\label{sec:group_separated}
231	
232	\begin{theorem}[The diagonal of a group object is a pullback of the unit]
233	  \label{thm:grp_diagonal_pullback}
234	  \lean{CategoryTheory.GrpObj.isPullback_diagonal}
235	  \uses{def:grp_diff}
236	  \leanok
237	  \source{kleiman-picard}
238	  Let \(G\) be a group object in a cartesian monoidal category, with unit
239	  \(e : 1 \to G\) and difference morphism
240	  \(\delta = \mathrm{pr}_1 \cdot \mathrm{pr}_2^{-1} : G \otimes G \to G\)
241	  (\ref{def:grp_diff}). Then the square
242	  \[
243	    \begin{array}{ccc}
244	      G & \xrightarrow{\ \Delta = \langle \mathrm{id}, \mathrm{id}\rangle\ }
245	        & G \otimes G \\
246	      \downarrow & & \downarrow \delta \\
247	      1 & \xrightarrow{\ e\ } & G
248	    \end{array}
249	  \]
250	  is a pullback: the diagonal of \(G\) is the base change of the unit along
251	  the difference map.
252	\end{theorem}
253	\begin{proof}
254	  \leanok
255	  \emph{Commutativity.} In the hom-group \(\Hom(G, G)\):
256	  \(\delta \circ \Delta = (\mathrm{pr}_1 \circ \Delta)\cdot(\mathrm{pr}_2
257	  \circ \Delta)^{-1} = \mathrm{id} \cdot \mathrm{id}^{-1} = 1\), the constant
258	  unit, which is the composite through the terminal object.
259	
260	  \emph{Universality.} Let \(s_1 : T \to 1\) and \(s_2 : T \to G \otimes G\)
261	  satisfy \(\delta \circ s_2 = e \circ s_1\). The right-hand side is the unit
262	  of \(\Hom(T, G)\), and the left-hand side is
263	  \((\mathrm{pr}_1 \circ s_2)\cdot(\mathrm{pr}_2 \circ s_2)^{-1}\); hence
264	  \(\mathrm{pr}_1 \circ s_2 = \mathrm{pr}_2 \circ s_2 =: h\). The morphism
265	  \(h : T \to G\) satisfies \(\Delta \circ h = \langle h, h \rangle = s_2\)
266	  (equal components) and \(t_G \circ h = s_1\) (morphisms to the terminal
267	  object agree). For uniqueness, any \(m\) with \(\Delta \circ m = s_2\) has
268	  \(m = \mathrm{pr}_1 \circ \Delta \circ m = \mathrm{pr}_1 \circ s_2 = h\).
269	\end{proof}
