271	\begin{theorem}[A group scheme with closed unit section is separated]
272	  \label{thm:separated_of_closed_unit}
273	  \lean{AlgebraicGeometry.isSeparated_of_isClosedImmersion_one}
274	  \uses{thm:grp_diagonal_pullback}
275	  \leanok
276	  \source{kleiman-picard}
277	  Let \(S\) be a scheme and \(G\) a group object of \(\Over(S)\). If the unit
278	  section \(e : S \to G\) is a closed immersion of schemes, then the structure
279	  morphism \(G \to S\) is separated. No finiteness hypothesis is required.
280	\end{theorem}
281	\begin{proof}
282	  \leanok
283	  Apply the forgetful functor \(\Over(S) \to \mathrm{Sch}\) to the pullback
284	  square of \ref{thm:grp_diagonal_pullback}; it preserves the square and its
285	  pullback property (fibre products in \(\Over(S)\) are computed on underlying
286	  schemes), and the monoidal product \(G \otimes G\) becomes the fibre product
287	  \(G \times_S G\) with \(\Delta\) the diagonal morphism of \(G\) over \(S\).
288	  Thus the diagonal \(\Delta_{G/S}\) is a base change of the closed immersion
289	  \(e\), and closed immersions are stable under base change; a morphism whose
290	  diagonal is a closed immersion is separated.
291	\end{proof}
