293	\begin{theorem}[Group schemes over a field are separated]
294	  \label{thm:group_scheme_separated}
295	  \lean{AlgebraicGeometry.isSeparated_of_grpObj}
296	  \uses{thm:separated_of_closed_unit}
297	  \leanok
298	  \source{kleiman-picard}
299	  Every group scheme \(G\) over a field \(K\) is separated over \(K\).
300	\end{theorem}
301	\begin{proof}
302	  \leanok
303	  The unit section \(e : \Spec K \to G\) of a group scheme over a field is a
304	  closed immersion: its image is a \(K\)-rational point, and a section of a
305	  \(K\)-scheme at a rational point is a closed immersion. Apply
306	  \ref{thm:separated_of_closed_unit}.
307	\end{proof}
