533	\section{The Abel source: properness and geometric irreducibility}
534	\label{sec:abel_source}
535	
536	\begin{definition}[Abel source]
537	  \label{def:abel_source}
538	  \lean{AlgebraicGeometry.AbelSourceData}
539	  \uses{def:jacobian_data}
540	  \leanok
541	  \source{abelian-varieties:page-0107}
542	  Let \(d\) be a Jacobian datum with representing object \(J\). An
543	  \emph{Abel source} for \(d\) consists of:
544	  \begin{enumerate}
545	    \item a scheme \(D\) over \(k\);
546	    \item a certificate that \(D\) is proper over \(k\);
547	    \item a certificate that \(D\) is geometrically irreducible over \(k\);
548	    \item an \emph{Abel morphism} \(a : D \to J\) over \(k\);
549	    \item a certificate that \(a\) is surjective on underlying topological
550	      spaces.
551	  \end{enumerate}
552	  (The intended instance takes \(D\) a proper scheme of effective divisors of
553	  large degree on \(C\) and \(a\) the Abel map; the results of this section
554	  are conditional on the interface only.)
555	\end{definition}
556	
557	\begin{theorem}[The representing object is universally closed]
558	  \label{thm:jacobianData_universallyClosed}
559	  \lean{AlgebraicGeometry.universallyClosed_of_abelSource}
560	  \uses{def:abel_source, def:jacobian_data}
561	  \leanok
562	  \source{abelian-varieties:page-0107}
563	  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
564	  morphism of the representing object \(J\) is universally closed.
565	\end{theorem}
566	\begin{proof}
567	  \leanok
568	  Let \(a : D \to J\) be the Abel morphism. Since \(a\) is a morphism over
569	  \(k\), the composite of \(a\) with the structure morphism of \(J\) is the
570	  structure morphism of \(D\), which is universally closed (\(D\) is proper).
571	  Surjectivity and closedness are stable under base change, so it suffices to
572	  see: if \(g \circ f\) is universally closed and \(f\) is surjective, then
573	  \(g\) is universally closed. Indeed, after any base change, for a closed
574	  subset \(Z\) of the source of the (base-changed) \(g'\),
575	  \(g'(Z) = (g' \circ f')\bigl(f'^{-1}(Z)\bigr)\) by surjectivity of the
576	  base-changed \(f'\), and the right-hand side is closed since
577	  \(g' \circ f' = (g \circ f)'\) is a closed map.
578	\end{proof}
579	
580	\begin{theorem}[The representing object is proper]
581	  \label{thm:jacobianData_proper}
582	  \lean{AlgebraicGeometry.isProper_of_abelSource}
583	  \uses{def:abel_source, cor:jacobianData_separated,
584	    thm:jacobianData_universallyClosed, def:jacobian_data}
585	  \leanok
586	  \source{abelian-varieties:page-0107}
587	  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
588	  morphism of the representing object \(J\) is proper.
589	\end{theorem}
590	\begin{proof}
591	  \leanok
592	  Properness is the conjunction of separatedness, universal closedness and
593	  finite type. Separatedness is \ref{cor:jacobianData_separated}; universal
594	  closedness is \ref{thm:jacobianData_universallyClosed}; the structure morphism
595	  is locally of finite type by the datum's certificate
596	  (\ref{def:jacobian_data}), and quasi-compact because universally closed
597	  morphisms are quasi-compact; locally of finite type and quasi-compact is
598	  finite type.
599	\end{proof}
